<?phpnamespace app\common\model\exchange;use app\common\model\BaseModel;use app\common\model\User as UserModel;use app\common\model\CouponUser as CouponUserModel;use think\facade\Db;/** * 订单模型 */class Order extends BaseModel{    // 定义表名    protected $name = 'exchange_order';    // 定义主键    protected $pk = 'order_id';    // 追加字段    protected $append = [];    /**     * 关联用户表     */    public function goods()    {        return $this->belongsTo('app\\common\\model\\exchange\\Goods','goods_id');    }        /**     * 关联用户表     */    public function user()    {        return $this->belongsTo('app\\common\\model\\User','user_id');    }        /**     * 领取状态     */     public function getReceiptStatusAttr($value)    {        $status = [10 => '待领取', 20 => '已领取'];        return ['text' => $status[$value], 'value' => $value];    }       /**     * 订单状态     */    public function getOrderStatusAttr($value)    {        $status = [10 => '进行中', 20 => '被取消', 30 => '已完成'];        return ['text' => $status[$value], 'value' => $value];    }        /**     * 按照分类获取单列表     * $type 类别 all=所有 payment=待付款 comment=待评价 refund=退款/售后     */    public function getList(string $dataType='all', string $search = '', int $user_id = 0)    {        // 筛选条件        $filter = [];        $user_id > 0 && $filter['user_id'] = $user_id;        $model = $this->with(['goods','goods.image','user'])            ->order(['order_id' => 'desc']);        switch ((string)$dataType) {            case 'all'; //全部                break;            case 'receipt';//待收货                $filter['receipt_status'] = 10;                $filter['order_status'] = 10;                break;            case 'cancel';//被取消                $filter['order_status'] = 20;                break;            case 'complete';//已完成                $filter['order_status'] = 30;                break;        }        return $model->where($filter)            ->paginate(['list_rows'=>15,'query' => request()->param()]);    }        /**     * 详情     */    public static function detail($id)    {        return self::with(['goods','goods' => ['image'], 'user'])            ->where(['order_id' => $id])            ->find();    }        /**     * 兑换下单     */    public function add(array $data)    {        $data['order_no'] = order_no();        $data['total_num'] = 1;        $data['total_price'] = $data['total_num'] * $data['goods_price'];          //库存操作        $goods = Goods::get($data['goods_id'],['coupon']);        $goods->stock_num = ['dec', $data['total_num']];//减少库存        $goods->goods_sales = ['inc', $data['total_num']];//增加销量                //积分操作        $user = UserModel::get($data['user_id']);        $user->converted = ['inc', $data['total_price']];//增加已兑换积分                // 开启事务        Db::startTrans();        try {            //如果兑换的是优惠券            if($goods['goods_type']['value'] == 20)            {                            $data['receipt_status'] = 20;//已领取                $data['receipt_time'] = time();                $data['order_status'] = 30;                        //发券操作                $model = new CouponUserModel;                $coupon = $model->dateTmp($goods['coupon'],$data['user_id']);                $model->save($coupon);            }            $goods->save();//商品操作            $user->save();//积分操作            $this->save($data);//添加订单            Db::commit();            return true;        } catch (\Exception $e) {            Db::rollback();        }    }        /**     * 取消订单     */    public function cancel()    {        //实物兑换才能进行取消操作        if($this->goods['goods_type']['value'] == 10){                        //实物退回            $goods = Goods::get($this->goods_id);            $goods->stock_num = ['inc', $this->total_num];//增加库存            $goods->goods_sales = ['dec', $this->total_num];//减少销量                        //退回积分            $user = UserModel::get($this->user_id);            $user->converted = ['dec', $score];//减少已兑换积分                    // 开启事务            Db::startTrans();            try {                $goods->save();//商品操作                $user->save();//积分操作                $this->save(['order_status' => 20]);// 取消订单                Db::commit();                return true;            } catch (\Exception $e) {                Db::rollback();            }        }        return false;    }    /**     * 确认完成     */    public function receipt()    {        $data = [            'receipt_status' => 20,            'receipt_time' => time(),            'order_status' => 30        ];        return $this->save($data) !== false;    }}